//! The C side of the libopus 1.6.1 neural network models, for the tests that
//! link a libopus built with them (`scripts/android/build-libopus.sh --dnn`).
//!
//! Generated by `tools/dnn-gen` from `dnn/*_data.h` and `dnn/*_data.c`. Do not
//! edit: change the generator and run it again (`tools/dnn-gen/README.md`).
//!
//! It holds `#[repr(C)]` copies of the C layer types and of each model struct,
//! the C symbols of each model (its `WeightArray` list and its init function),
//! and `MODELS`: one entry per model, the DRED models included, with the layer
//! descriptors in the order of the C init function.

// Each test file uses only a part of this module, and the structs keep
// the names of the C structs.
#![allow(dead_code, clippy::upper_case_acronyms)]

use opus1::internals::dnn::models::{Conv2dSpec, LayerSpec, LinearSpec};
use std::os::raw::{c_char, c_int, c_void};

/// `LinearLayer` of `dnn/nnet.h:66-76`.
#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct CLinearLayer {
    pub bias: *const f32,
    pub subias: *const f32,
    pub weights: *const i8,
    pub float_weights: *const f32,
    pub weights_idx: *const c_int,
    pub diag: *const f32,
    pub scale: *const f32,
    pub nb_inputs: c_int,
    pub nb_outputs: c_int,
}

/// `Conv2dLayer` of `dnn/nnet.h:79-86`.
#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct CConv2dLayer {
    pub bias: *const f32,
    pub float_weights: *const f32,
    pub in_channels: c_int,
    pub out_channels: c_int,
    pub ktime: c_int,
    pub kheight: c_int,
}

/// `WeightArray` of `dnn/nnet.h:44-49`.
#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct CWeightArray {
    pub name: *const c_char,
    pub kind: c_int,
    pub size: c_int,
    pub data: *const c_void,
}

/// One layer of a C model struct.
#[derive(Clone, Copy, Debug)]
pub enum CLayer {
    Linear(CLinearLayer),
    Conv2d(CConv2dLayer),
}

/// One model of libopus.
pub struct CModel {
    /// The name of the data file without `_data.c`, which is also the name
    /// of the model's blob in `dnn-weights/`.
    pub key: &'static str,
    /// The opus1 feature that includes the model (`dred` for the two DRED
    /// models, which opus1 does not include yet).
    pub feature: &'static str,
    /// The C struct of the model.
    pub c_struct: &'static str,
    /// The layer descriptors, in the order of the C init function.
    pub layers: &'static [LayerSpec],
    /// The C list of arrays (`*_arrays`), which ends with a `NULL` name.
    pub arrays: fn() -> *const CWeightArray,
    /// Runs the C init function on a list: its return value, and the
    /// layers in the order of `layers`.
    pub init: fn(*const CWeightArray) -> (c_int, Vec<CLayer>),
}

