fn c_pitchdnn_init(arrays: *const CWeightArray) -> (c_int, Vec<CLayer>) {
    // SAFETY: the struct holds only pointers and integers, so all zeros is a
    // valid value (null pointers, zero sizes). The init function reads the
    // list up to its end entry and writes only the struct.
    let mut m: CPitchDNN = unsafe { std::mem::zeroed() };
    let ret = unsafe { init_pitchdnn(&mut m, arrays) };
    let layers = vec![
        CLayer::Linear(m.dense_if_upsampler_1),
        CLayer::Linear(m.dense_if_upsampler_2),
        CLayer::Linear(m.dense_downsampler),
        CLayer::Linear(m.dense_final_upsampler),
        CLayer::Conv2d(m.conv2d_1),
        CLayer::Conv2d(m.conv2d_2),
        CLayer::Linear(m.gru_1_input),
        CLayer::Linear(m.gru_1_recurrent),
    ];
    (ret, layers)
}

